function parseThresholds(thresholdStrings?: string[]): { [key: string]: number } | null {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const result: { [key: string]: number } = {};
  for (const str of thresholdStrings) {
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: ${str}. Expected format: <metric>=<number>`);
    }
    const metricId = match[1];
    const minValue = Number.parseFloat(match[2]);
    if (Number.isNaN(minValue) || minValue < 0 || minValue > 1) {
      throw new Error(`Invalid threshold for ${metricId}: must be a number between 0 and 1, got ${minValue}`);
    }
    result[metricId] = minValue;
  }
  return result;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: { [key: string]: number } | null = null;
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    log.error((error as Error).message);
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  // Validate thresholds against known metrics
  if (thresholds) {
    const errors = (Eval.validateThresholds as unknown as (thresholds: unknown, metrics: unknown) => string[])(
      thresholds,
      evaluations
    );
    if (errors.length > 0) {
      log.error('Invalid thresholds:');
      errors.forEach((error) => console.error(` - ${error}`));
      process.exit(2);
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: thresholds ?? {}
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && Object.keys(thresholds).length > 0) {
    if (report.passed) {
      log.success('All thresholds passed.');
    } else {
      log.error('Some thresholds failed.');
      process.exit(1);
    }
  }
}

