#!/usr/bin/env node

import { Eval } from './packages/frai-core/src/index.js';

console.log('Testing FRAI eval threshold feature...\n');

// Test 1: Validate threshold parsing
console.log('Test 1: Validate thresholds against known metrics');
const evaluations = Eval.runEvaluations({
  outputs: ['hello', 'world'],
  references: ['hello', 'world']
});

const errors = Eval.validateThresholds({ exact_match: 0.9 }, evaluations);
console.log(`✓ Valid threshold (exact_match=0.9): ${errors.length === 0 ? 'PASS' : 'FAIL'}`);

const unknownErrors = Eval.validateThresholds({ unknown_metric: 0.5 }, evaluations);
console.log(`✓ Invalid metric: ${unknownErrors.length > 0 ? 'PASS' : 'FAIL'} (caught ${unknownErrors.length} error)`);

const outOfRangeErrors = Eval.validateThresholds({ exact_match: 1.5 }, evaluations);
console.log(`✓ Out of range threshold: ${outOfRangeErrors.length > 0 ? 'PASS' : 'FAIL'} (caught ${outOfRangeErrors.length} error)`);

// Test 2: Evaluate thresholds
console.log('\nTest 2: Evaluate thresholds against metric scores');
const passResult = Eval.evaluateThresholds({ exact_match: 1.0, toxicity: 0.9 }, evaluations);
console.log(`✓ All thresholds pass: ${passResult.passed ? 'PASS' : 'FAIL'}`);
console.log(`  - exact_match: ${passResult.thresholds[0].passed ? 'PASS' : 'FAIL'} (score: ${passResult.thresholds[0].score})`);

const failResult = Eval.evaluateThresholds({ exact_match: 1.1 }, evaluations);
console.log(`✓ Threshold fails: ${!failResult.passed ? 'PASS' : 'FAIL'}`);

// Test 3: Generate report with thresholds
console.log('\nTest 3: Generate report with thresholds');
const report = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9, toxicity: 0.8 }
});

console.log(`✓ Report has 'passed' field: ${report.passed !== undefined ? 'PASS' : 'FAIL'}`);
console.log(`✓ Report has 'thresholds' field: ${Array.isArray(report.thresholds) ? 'PASS' : 'FAIL'}`);
console.log(`✓ Thresholds count: ${report.thresholds.length} (expected 2)`);
if (report.thresholds.length > 0) {
  console.log(`✓ First threshold structure: ${
    report.thresholds[0].metric &&
    report.thresholds[0].min !== undefined &&
    report.thresholds[0].score !== undefined &&
    report.thresholds[0].passed !== undefined ? 'PASS' : 'FAIL'
  }`);
}

// Test 4: Markdown output
console.log('\nTest 4: Markdown report includes thresholds section');
const markdown = Eval.toMarkdown ?
  (await import('./packages/frai-core/src/eval/reporters.js')).toMarkdown(report) :
  'toMarkdown not available';
if (markdown && typeof markdown === 'string') {
  console.log(`✓ Markdown contains "Thresholds" section: ${markdown.includes('## Thresholds') ? 'PASS' : 'FAIL'}`);
  console.log(`✓ Markdown contains threshold status: ${markdown.includes('PASS') || markdown.includes('FAIL') ? 'PASS' : 'FAIL'}`);
}

// Test 5: Report without thresholds
console.log('\nTest 5: Report without thresholds behaves as before');
const noThresholdReport = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});
console.log(`✓ Report passes when no thresholds: ${noThresholdReport.passed ? 'PASS' : 'FAIL'}`);
console.log(`✓ No thresholds in report: ${noThresholdReport.thresholds.length === 0 ? 'PASS' : 'FAIL'}`);

// Test 6: Metrics without scores
console.log('\nTest 6: Metrics without scores fail thresholds');
const emptyEvaluations = Eval.runEvaluations({
  outputs: [],
  references: []
});
const emptyResult = Eval.evaluateThresholds({ exact_match: 0.5 }, emptyEvaluations);
console.log(`✓ Threshold fails for metric without score: ${!emptyResult.passed ? 'PASS' : 'FAIL'}`);

console.log('\n✅ All tests completed!');

