62	export function validateThresholds(thresholds, metrics) {
63	  const errors = [];
64	  const validMetricIds = new Set(metrics.map((m) => m.id));
65	
66	  for (const [metricId, minValue] of Object.entries(thresholds || {})) {
67	    if (!validMetricIds.has(metricId)) {
68	      errors.push(`Unknown metric id: ${metricId}. Valid metrics: ${Array.from(validMetricIds).join(', ')}`);
69	      continue;
70	    }
71	    if (typeof minValue !== 'number' || minValue < 0 || minValue > 1) {
72	      errors.push(`Invalid threshold for ${metricId}: must be a number between 0 and 1, got ${minValue}`);
73	    }
74	  }
75	
76	  return errors;
77	}
78	
79	export function evaluateThresholds(thresholds, metrics) {
80	  if (!thresholds || Object.keys(thresholds).length === 0) {
81	    return { passed: true, thresholds: [] };
82	  }
83	
84	  const results = [];
85	  let allPassed = true;
86	
87	  for (const [metricId, min] of Object.entries(thresholds)) {
88	    const metric = metrics.find((m) => m.id === metricId);
89	    const score = metric?.score ?? null;
90	    const passed = score !== null && score >= min;
91	    if (!passed) allPassed = false;
92	    results.push({ metric: metricId, min, score, passed });
93	  }
94	
95	  return { passed: allPassed, thresholds: results };
96	}
97	
98	export function generateReport({
99	  evaluations,
100	  outputsPath,
101	  referencesPath,
102	  generatedAt = new Date().toISOString(),
103	  thresholds = {}
104	}) {
105	  const totalSamples = evaluations.reduce((total, metric) => {
106	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
107	    return total;
108	  }, 0);
109	
110	  const thresholdResults = evaluateThresholds(thresholds, evaluations);
111	
112	  return {
113	    metadata: {
114	      generatedAt,
115	      outputsPath,
116	      referencesPath,
117	      totalSamples
118	    },
119	    metrics: evaluations,
120	    passed: thresholdResults.passed,
121	    thresholds: thresholdResults.thresholds

